def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    opp_last = history[-1][1]
    my_last = history[-1][0]

    # Count mutual cooperation and defection patterns
    cc = dd = cd = dc = 0
    for a, b in history:
        if a == 'C' and b == 'C':
            cc += 1
        elif a == 'D' and b == 'D':
            dd += 1
        elif a == 'C' and b == 'D':
            cd += 1
        else:
            dc += 1

    # Near endgame: if we're close to end, defect to grab DC if opponent likely cooperates
    if n >= 97:
        # If opponent has cooperated very often, exploit
        if cc + cd > n * 0.7:
            return 'D'
        # If opponent mostly defects, defect too
        if dd > n * 0.5:
            return 'D'
        return 'C'

    # Detect probable always-defect or mostly-defect
    if n >= 5 and dd >= n - 2:
        return 'D'

    # Detect probable always-cooperate or mostly-cooperate
    if n >= 5 and (cc + cd) >= n - 2 and dc <= 1:
        return 'C'

    # Tit-for-tat core with forgiveness
    if opp_last == 'C':
        return 'C'

    # Opponent defected last. Decide whether to retaliate.
    # If opponent has a mostly cooperative history, forgive occasionally
    total = n
    coop_rate = (cc + dc) / total if total else 0

    if coop_rate > 0.6:
        # Forgive with some probability, but ensure we don't get exploited too often
        if rng.random() < 0.35:
            return 'C'
        return 'D'
    elif coop_rate > 0.3:
        # Moderate: alternate retaliation
        if n >= 2 and history[-2][1] == 'D':
            return 'D'
        return 'D' if rng.random() < 0.7 else 'C'
    else:
        # Low cooperation: mostly defect
        if rng.random() < 0.85:
            return 'D'
        return 'C'
